  "pp.abs.h4": "حوضه آبخیز فولادمحله — مهدیشهر",
  "pp.abs.p1": "این پروژه با هدف توسعه یک چارچوب هوشمند، داده‌محور و مبتنی بر هوش مصنوعی برای تحلیل و مدیریت حوضه‌های آبخیز طراحی و اجراء شده است. در این پژوهش، با تلفیق فناوری‌های سنجش از دور (Remote Sensing)، سامانه اطلاعات جغرافیایی (GIS)، کلان‌داده‌های اقلیمی (Climate Big Data)، مدل‌سازی رقومی زمین (Digital Terrain Modeling) و الگوریتم‌های یادگیری ماشین (Machine Learning)، بستری یکپارچه برای تحلیل رفتار هیدرولوژیکی و ژئومورفولوژیکی حوضه ایجاد گردید.",
  "pp.abs.p2": "وجه تمایز این پروژه نسبت به مطالعات متداول، تغییر رویکرد از تحلیل‌های کلاسیک به تحلیل‌های هوشمند مبتنی بر داده است؛ به‌گونه‌ای که تصمیم‌گیری‌های مدیریتی نه بر اساس روابط تجربی محدود، بلکه بر پایه پردازش هم‌زمان داده‌های چندمنبعی، مدل‌های پیش‌بینی و تحلیل‌های پیشرفته مکانی انجام شده است.",
