  "det.hero.desc": "«روش‌های نوین در مطالعات آبخیزداری» به‌عنوان نخستین پروژه آغازین هسته پویاب، بر پایه یک چارچوب هوشمند، داده‌محور و مکان‌مبنا اجرا شده است؛ چارچوبی که مطالعات سنتی آبخیزداری را به یک سامانه تحلیل، پیش‌بینی و تصمیم‌سازی ارتقا می‌دهد.",
  "det.hero.tag1": "آبخیزداری",
  "det.hero.tag2": "کنترل سیل",
