  "det.eros.stat4.num": "۲۹٫۶٪",
  "det.eros.stat4.label": "بیشترین مساحت در کلاس فرسایش متوسط",
  "det.maps.eyebrow": "گالری نقشه‌ها",
  "det.maps.title": "نقشه‌های پروژه",
  "det.maps.desc": "خروجی‌های مکانی تولیدشده در فرآیند مطالعات حوضه در گالری زیر آمده است؛ با کلیک روی هر نقشه، نمای بزرگ آن باز می‌شود.",
  "det.maps.cap1": "کاور پروژه — نمای کلی حوضه",
