  /* ---------- پروژه ۰۲ — جدول و چکیده ---------- */
  "pp.tab.row2.title": "تهیه سیستم پشتیبان تصمیم‌گیری برای مکان‌یابی و اولویت‌بندی نواحی مستعد احداث پخش سیلاب",
  "pp.tab.row2.basin": "استان سمنان",
  "pp.tab.row2.status": "تکمیل‌شده",
  "pp.abs2.title": "تهیه سیستم پشتیبان تصمیم‌گیری برای مکان‌یابی و اولویت‌بندی نواحی مستعد احداث پخش سیلاب",
  "pp.abs2.basin": "حوضه مورد مطالعه: استان سمنان",
  "pp.abs2.imgAlt": "پروژه مکان‌یابی پخش سیلاب — استان سمنان",
  "pp.abs2.badge": "پروژه ۰۲",
  "pp.abs2.status": "پروژه کاربردی — استان سمنان",
  "pp.abs2.h3": "یک سامانه پشتیبان تصمیم برای مکان‌یابی پخش سیلاب",
  "pp.abs2.h4": "استان سمنان — ۴۹ نقطه مستعد احداث",
  "pp.abs2.p1": "این پروژه با هدف توسعه یک سیستم پشتیبان تصمیم‌گیری داده‌محور برای مکان‌یابی و اولویت‌بندی نواحی مستعد احداث پخش سیلاب در استان سمنان طراحی و اجرا شده است. در این پژوهش با تلفیق یادگیری ماشین، نقشه‌برداری رقومی خاک (DSM)، داده‌های بازتحلیل اقلیمی ERA5-Land و تصاویر ماهواره لندست ۸، نقشه‌های دقیق خصوصیات خاک، اقلیم و پوشش سطح زمین در سطح استان تولید شد؛ نقشه‌هایی که از حدود ۷۰۰ نمونه خاک، ۱۱۰۰ نقطه عمق خاک و ۴۶۰ نقطه نمونه‌برداری تاج‌پوشش گیاهی پشتیبانی می‌شوند.",
  "pp.abs2.p2": "با بهره‌گیری از ۱۹ متغیر کمکی، مدل‌های یادگیری ماشین (Random Forest، SVR، Treebag، Glmnet و Ensemble) و الگوریتم انتخاب ویژگی Boruta، پهنه‌های سیل‌خیز استان استخراج و نقشه شماره منحنی (CN) و ارتفاع رواناب با روش SCS تهیه و کالیبره شد. در نهایت با اعمال معیارهای شیب ۱ تا ۵ درصد، فاصله از آبراهه، عمق خاک، کاربری اراضی و وجود آبخوان، ۴۹ نقطه مستعد احداث پخش سیلاب مکان‌یابی و با بازدیدهای میدانی صحت‌سنجی شد.",
  "pp.abs2.meta1": "پخش سیلاب",
  "pp.abs2.meta2": "یادگیری ماشین",
  "pp.abs2.meta3": "نقشه‌برداری رقومی خاک",
  "pp.abs2.meta4": "تصمیم‌گیری مکانی",

  "det2.hero.eyebrow": "پروژه ۰۲ — جزئیات",
  "det2.hero.title": "سامانه پشتیبان تصمیم برای مکان‌یابی پخش سیلاب در استان سمنان",
  "det2.hero.h2": "استان سمنان",
  "det2.hero.desc": "این پروژه با ترکیب داده‌های خاک، اقلیم، سنجش از دور و مدل‌های یادگیری ماشین، چارچوبی یکپارچه برای مکان‌یابی و اولویت‌بندی عرصه‌های مستعد احداث پخش سیلاب در استان سمنان فراهم می‌کند؛ خروجی این پژوهش، نقشه نهایی ۴۹ نقطه مستعد همراه با تحلیل شرایط بالادست آن‌هاست.",
