  "det2.maps.cap22": "کاربری اراضی (LULC)",
  "det2.maps.cap23": "کربن آلی خاک",
  "det2.res.eyebrow": "دستاوردهای طرح",
  "det2.res.title": "از داده‌های پراکنده تا نقشه نهایی مکان‌یابی",
  "det2.res.p1": "مهم‌ترین دستاورد این طرح، تولید نخستین مجموعه نقشه‌های رقومی پایه (خاک، اقلیم و پوشش زمین) در سطح استان سمنان و تبدیل آن‌ها به یک سیستم پشتیبان تصمیم‌گیری برای پخش سیلاب است. پهنه‌های سیل‌خیز با چهار روش داده‌کاوی و با دقت قابل ارزیابی استخراج، نقشه‌های شماره منحنی و ارتفاع رواناب تهیه و کالیبره شد و در نهایت ۴۹ عرصه مستعد احداث پخش سیلاب در قالب یک نقشه نهایی ارائه و با بازدیدهای میدانی راستی‌آزمایی شد.",
  "det2.res.p2": "این زیرساخت فناورانه علاوه بر مکان‌یابی پخش سیلاب، در مدیریت آبخوان‌ها، برنامه‌ریزی منابع آب، پایش گرد و غبار و پشتیبانی از تصمیم‌گیری‌های کلان منابع طبیعی در استان سمنان قابل استفاده است و با ورود داده‌های جدید، به‌سادگی به‌روزرسانی می‌شود.",
  "det2.fut.eyebrow": "مسیر آینده",
  "det2.fut.title": "توسعه سامانه به سایر کاربردها",
  "det2.fut.p1": "با تکمیل نقشه‌های رقومی خاک استان (افزایش نقاط نمونه‌برداری از حدود ۷۰۰ به بیش از ۵۰۰۰ نقطه مورد نیاز)، توسعه پایگاه داده مکانی، استفاده از تصاویر راداری برای پایش مناطق سیلابی در اراضی خشک و نیمه‌خشک و اتصال نتایج به سامانه‌های پایش آنلاین، این زیرساخت می‌تواند به پلتفرمی ملی برای مکان‌یابی طرح‌های آبخیزداری و تغذیه مصنوعی تبدیل شود.",

  /* ---------- پروژه ۰۳ — جدول و چکیده ---------- */
  "pp.tab.row3.title": "بررسی کارایی مالچ سنگریزه‌ای بر کنترل فرسایش بادی (مطالعه موردی منطقه گرمسار)",
  "pp.tab.row3.basin": "منطقه گرمسار، استان سمنان",
  "pp.tab.row3.status": "تکمیل‌شده",
  "pp.abs3.title": "بررسی کارایی مالچ سنگریزه‌ای بر کنترل فرسایش بادی",
  "pp.abs3.basin": "منطقه مورد مطالعه: منطقه گرمسار، استان سمنان",
  "pp.abs3.imgAlt": "پروژه مالچ سنگریزه‌ای — گرمسار",
  "pp.abs3.badge": "پروژه ۰۳",
  "pp.abs3.status": "پروژه پژوهشی-کاربردی",
  "pp.abs3.h3": "مالچ سنگریزه‌ای؛ راهکاری پایدار برای مهار فرسایش بادی",
  "pp.abs3.h4": "منطقه گرمسار — تونل باد و مطالعات میدانی",
  "pp.abs3.p1": "در این پروژه، کارایی مالچ سنگریزه‌ای در کنترل فرسایش بادی در اراضی بیابانی منطقه گرمسار با ترکیب آزمایش‌های تونل باد و مطالعات میدانی ارزیابی شد. منطقه مورد مطالعه با بارش سالانه حدود ۱۱۷ میلی‌متر، تبخیر و تعرق بیش از ۲۵۵۰ میلی‌متر، بادهای غالب غربی–شرقی و خاک‌های گچی و شور، از مستعدترین عرصه‌ها برای فرسایش بادی است. تأثیر هفت تیمار پوشش سنگریزه (۱۰ تا ۷۰ درصد) در شش سرعت باد در قالب آزمایش فاکتوریل با طرح کاملاً تصادفی و سه تکرار آزمون شد.",
  "pp.abs3.p2": "نتایج نشان داد مالچ سنگریزه‌ای فرسایش بادی را بیش از ۹۸ درصد کاهش می‌دهد (از ۲۲.۷۳ گرم در تیمار شاهد به ۰.۳۹ گرم در پوشش ۷۰ درصد) و تیمارهای ۵۰، ۶۰ و ۷۰ درصد بهترین عملکرد را دارند. افزایش رطوبت خاک به ۲ درصد نیز فرسایش را بیش از ۹۹ درصد کاهش داد. از منظر اقتصادی، هزینه اجرای مالچ‌پاشی در پوشش‌های انتخابی بین ۱۳۰ تا ۲۵۲ میلیون تومان در هکتار برآورد شد و پوشش ۵۰ درصد به‌عنوان گزینه پیشنهادی معرفی گردید.",
  "pp.abs3.meta1": "مالچ سنگریزه‌ای",
  "pp.abs3.meta2": "فرسایش بادی",
  "pp.abs3.meta3": "تونل باد",
  "pp.abs3.meta4": "مدیریت بیابان",

