  "leader.role": "Lead Advisor and Scientific Supervisor of the Core",
  "leader.p1": "Dr. Ali-Asghar Zolfaghari is an Associate Professor in the Desertification Control Department and Head of the Faculty of Desert Studies at Semnan University. He holds a bachelor's degree from the University of Guilan, a master's from Isfahan University of Technology, and a Ph.D. from the University of Tehran. His areas of specialization include desertification control, soil and water, soil erosion, hydrology, climate change, remote sensing and GIS, environmental modeling, and the application of machine learning in natural resource sciences.",
