  "pp.hero.eyebrow": "Pouyab Research Projects",
  "pp.hero.title": "It Begins with a Problem and Reaches a Solution",
  "pp.hero.desc": "The Pouyab core turns real-world problems in natural resources and watershed management into problem-driven projects, built on data-driven analysis, smart modeling, and usable outputs.",
