  "det.act.eyebrow": "Completed Activities",
  "det.act.title": "Field and Technical Implementation",
  "det.act1.t": "Expert Meeting and Project Execution Planning",
  "det.act1.d": "Holding expert meetings to formulate the implementation roadmap and ensure inter-sectoral coordination.",
  "det.act2.t": "Field Visit to the Basin",
  "det.act2.d": "Visiting the watershed together with experts from the Natural Resources Organization, council and village-delegation members, and project members.",
  "det.act3.t": "Water and Soil Sampling and Testing",
  "det.act3.d": "Performing water and soil sampling and testing to support erosion modeling and hydrological simulation.",
  "det.gal.eyebrow": "Activities Gallery",
  "det.gal.title": "Visual Report of the Project",
  "det.gal.desc": "The field and technical activities of the project are recorded chronologically in the frames below; each frame will be completed as its photo becomes available.",
  "det.tl1.ph": "Photo placeholder \u2014 expert meeting",
  "det.tl1.t": "Expert Meeting and Project Execution Planning",
  "det.tl1.d": "Inter-sectoral coordination sessions and formulation of the implementation roadmap with experts and core members.",
  "det.tl2.ph": "Photo placeholder \u2014 field visit",
  "det.tl2.t": "Field Visit to the Basin with Experts",
  "det.tl2.d": "Field survey of the watershed accompanied by the Natural Resources Organization, council and village-delegation members, and project members.",
  "det.tl3.ph": "Photo placeholder \u2014 sampling",
  "det.tl3.t": "Water and Soil Sampling and Testing",
  "det.tl3.d": "Collecting water and soil samples and performing laboratory tests for accurate modeling of basin behavior.",
  "det.tl4.ph": "Photo placeholder \u2014 analysis and modeling",
  "det.tl4.t": "Data Analysis and Smart Modeling",
  "det.tl4.d": "Integrating multi-source data, hydrological modeling, and producing spatial and analytical outputs.",
  "det.adv.eyebrow": "Competitive Advantage",
  "det.adv.title": "How This Project Differs from Conventional Studies",
  "det.adv.p": "This project goes beyond a merely descriptive study and, by establishing a comprehensive spatial analysis base, enables the accurate modeling of the basin's behavior.",
  "det.adv1": "Higher accuracy of hydrological and geomorphological analyses through multi-source data processing.",
  "det.adv2": "Reduced uncertainty in the management decision-making process.",
  "det.adv3": "Lower cost and time of field studies through geomatics technologies.",
  "det.adv4": "Ability to rapidly update information as new data arrives.",
  "det.adv5": "Production of standardized outputs usable in national watershed projects.",
  "det.adv6": "Providing the infrastructure needed to develop smart natural-resource management systems.",
  "det.techach.eyebrow": "Technological Achievement",
  "det.techach.title": "From a Descriptive Study to a Prediction and Decision-Making System",
  "det.techach.p1": "By building a smart architecture based on satellite data, climate big data, geospatial analyses, and machine learning algorithms, this research has elevated the watershed study process from a traditional and descriptive method to an advanced system of analysis, prediction, and decision-making. The simultaneous integration of ERA5-Land, CHIRPS, and IMERG data with machine learning models and GIS analyses has enabled the identification of hidden patterns, reduced uncertainty, higher prediction accuracy, lower field-data collection costs, and optimized management decisions.",
  "det.techach.p2": "From a technological standpoint, this project is an example of applying artificial intelligence and advanced geospatial analyses in natural-resource management, and it can be extended to smart monitoring systems, natural-hazard prediction, flood management, erosion assessment, and data-driven watershed planning.",
  "det.future.eyebrow": "Technology Development Horizon",
  "det.future.title": "Future Path and National Value-Added",
  "det.future.p1": "The infrastructure created in this project can be extended to a new generation of smart natural-resource management systems and can serve as a basis for the development of continuous watershed monitoring systems, prediction-based analyses, environmental-risk assessment, and decision-support systems in land planning. This project is not merely an executive study but a technological platform for data-driven natural-resource management.",
  "det.future.p2": "Through the synergy of artificial intelligence, remote sensing, satellite and climatic data, GIS, and hydrological modeling, this project offers a novel model for the smart management of watersheds \u2014 an outcome that is not just the production of maps or reports but the creation of an expandable, reproducible, and localizable technological framework for other watersheds across the country.",
"det.back": "Back to Project List",

