  /* ---------- Project 02 — table & abstract ---------- */
  "pp.tab.row2.title": "Developing a Decision Support System for Locating and Prioritizing Areas Suitable for Floodwater Spreading",
  "pp.tab.row2.basin": "Semnan Province",
  "pp.tab.row2.status": "Completed",
  "pp.abs2.title": "Developing a Decision Support System for Locating and Prioritizing Areas Suitable for Floodwater Spreading",
  "pp.abs2.basin": "Study area: Semnan Province",
  "pp.abs2.imgAlt": "Floodwater spreading site-selection project — Semnan Province",
  "pp.abs2.badge": "Project 02",
  "pp.abs2.status": "Applied project — Semnan Province",
  "pp.abs2.h3": "A Decision Support System for Siting Floodwater Spreading",
  "pp.abs2.h4": "Semnan Province — 49 suitable sites",
  "pp.abs2.p1": "This project was designed and implemented to develop a data-driven decision support system for locating and prioritizing areas suitable for floodwater spreading in Semnan Province. By integrating machine learning, digital soil mapping (DSM), ERA5-Land reanalysis climate data, and Landsat 8 imagery, detailed maps of soil properties, climate, and land cover were produced for the entire province — layers supported by roughly 700 soil samples, 1,100 soil-depth points, and 460 canopy-cover sampling points.",
  "pp.abs2.p2": "Using 19 auxiliary covariates, machine learning models (Random Forest, SVR, Treebag, Glmnet, and Ensemble), and the Boruta feature-selection algorithm, the province's flood-prone zones were extracted, and Curve Number (CN) and runoff-depth maps were derived and calibrated with the SCS method. Finally, by applying criteria such as slope (1–5%), distance from watercourses, soil depth, land use, and the presence of aquifers, 49 suitable floodwater spreading sites were located, field-validated, and delivered as a final map.",
  "pp.abs2.meta1": "Floodwater Spreading",
  "pp.abs2.meta2": "Machine Learning",
  "pp.abs2.meta3": "Digital Soil Mapping",
  "pp.abs2.meta4": "Spatial Decision Making",

  "det2.hero.eyebrow": "Project 02 — Details",
  "det2.hero.title": "A Decision Support System for Locating Floodwater Spreading in Semnan Province",
  "det2.hero.h2": "Semnan Province",
  "det2.hero.desc": "Combining soil, climate, remote-sensing data, and machine learning models, this project provides an integrated framework for locating and prioritizing areas suitable for floodwater spreading in Semnan Province. Its outcome is a final map of 49 suitable sites, accompanied by an analysis of their upstream conditions.",
  "det2.hero.tag1": "Floodwater Spreading",
  "det2.hero.tag2": "Machine Learning",
  "det2.hero.tag3": "Digital Soil Mapping",
  "det2.hero.tag4": "ERA5-Land Climate Data",
  "det2.hero.tag5": "Remote Sensing",
  "det2.hero.tag6": "Spatial Decision Support",
  "det2.spec.eyebrow": "General Specifications",
  "det2.spec.title": "Project Profile",
  "det2.spec.k1": "Project Title",
  "det2.spec.v1": "Developing a Decision Support System for Locating and Prioritizing Areas Suitable for Floodwater Spreading in Semnan Province",
  "det2.spec.k2": "Study Area",
  "det2.spec.v2": "Semnan Province (processing of station, field, and satellite data at the provincial scale)",
  "det2.spec.k3": "Client / Scientific Partner",
  "det2.spec.v3": "Semnan Provincial Office of Natural Resources and Watershed Management (client); University of Semnan (scientific partner)",
  "det2.spec.k4": "Lead Advisor",
  "det2.spec.v4": "Dr. Ali-Asghar Zolfaghari",
  "det2.spec.k5": "Core Team",
  "det2.spec.v5": "Zahra Sheikh (postdoc, Hydrology); Maryam Raeisi (Ph.D., Climate and Climate Modeling); Azadeh Soltani (Ph.D., GIS and Geomorphology); Mehdi Yaghoubzadeh (B.Sc. in Nature Engineering, Sampling and Laboratory)",
  "det2.spec.k6": "Field Data",
