  "leader.eyebrow": "团队介绍",
  "leader.name": "阿里·阿斯加尔·佐勒法加里博士",
  "leader.role": "核心团队首席顾问与学术督导",
  "leader.p1": "阿里·阿斯加尔·佐勒法加里博士是塞姆南大学荒漠化防治系副教授、荒漠科学学院院长。他在吉兰大学获得学士学位，在伊斯法罕理工大学获得硕士学位，在德黑兰大学获得博士学位。其研究和专业领域包括荒漠化防治、水土、土壤侵蚀、水文学、气候变化、遥感和地理信息系统、环境建模以及机器学习在自然资源科学中的应用。",
  "leader.p2": "他在塞姆南大学拥有丰富的教学、科研和行政经验，并积极发表学术论文、开展自然资源与环境领域的研究项目。",
  "leader.quote": "目标是构建一条始于真实问题、通达知识、解决方案与可衡量影响的研究之路。",
  "leader.imgAlt": "首席顾问照片",
  "leader.cardName": "阿里·阿斯加尔·佐勒法加里博士",
  "leader.cardTitle": "首席顾问",
