  "det.tl3.ph": "图片占位 — 采样",
  "det.tl3.t": "水土采样与检测",
  "det.tl3.d": "采集水土样品并开展实验室检测，为精准模拟流域行为提供支撑。",
  "det.tl4.ph": "图片占位 — 分析与建模",
  "det.tl4.t": "数据分析与智能建模",
  "det.tl4.d": "整合多源数据、开展水文建模并产出空间与分析成果。",
  "det.adv.eyebrow": "竞争优势",
  "det.adv.title": "本项目与常规研究的区别",
  "det.adv.p": "本项目超越了单纯的描述性研究，通过建立综合空间分析平台，实现了对流域行为的精准建模。",
  "det.adv1": "通过多源数据处理提升水文与地貌分析的精度。",
  "det.adv2": "降低管理决策过程中的不确定性。",
  "det.adv3": "依托地理信息工程技术，降低外业研究的成本与时间。",
  "det.adv4": "新数据到位后具备快速更新信息的能力。",
  "det.adv5": "产出标准化、可用于国家流域项目的成果。",
  "det.adv6": "为发展自然资源智能管理系统奠定必要的基础设施。",
  "det.techach.eyebrow": "技术成果",
  "det.techach.title": "从描述性研究走向预测与决策系统",
  "det.techach.p1": "本研究通过构建基于卫星数据、气候大数据、地理空间分析与机器学习算法的智能架构，将流域研究流程从传统、描述性的方法提升为集分析、预测与决策于一体的先进系统。ERA5-Land、CHIRPS 与 IMERG 数据同机器学习模型及 GIS 分析的同步整合，使识别隐藏模式、降低不确定性、提高预测精度、减少外业数据采集成本并优化管理决策成为可能。",
  "det.techach.p2": "从技术角度看，本项目是人工智能与先进地理空间分析在自然资源管理领域应用的范例，并可扩展至智能监测系统、自然灾害预测、洪水管理、侵蚀评估以及流域数据驱动规划之中。",
  "det.future.eyebrow": "技术发展前景",
  "det.future.title": "未来路径与国家增值",
  "det.future.p1": "本项目建立的基础设施可扩展至新一代自然资源智能管理系统，并可成为持续流域监测系统、预测性分析、环境风险评估以及国土规划中决策支持系统的发展基础。本项目并不仅是执行性研究，更是面向数据驱动的自然资源管理的技术平台。",
  "det.future.p2": "通过人工智能、遥感、卫星与气候数据、GIS 与水文建模之间的协同，本项目为流域智能治理提供了全新范式；其成果不仅在于制图或报告，更在于为国内其他流域构建一套可扩展、可复现、可本土化的技术框架。",
"det.back": "返回项目列表",

