  /* ---------- 项目02 — 表格与摘要 ---------- */
  "pp.tab.row2.title": "开发决策支持系统以选址和排序塞姆南省适合建设拦蓄洪水工程的地区",
  "pp.tab.row2.basin": "塞姆南省",
  "pp.tab.row2.status": "已完成",
  "pp.abs2.title": "开发决策支持系统以选址和排序塞姆南省适合建设拦蓄洪水工程的地区",
  "pp.abs2.basin": "研究区域：塞姆南省",
  "pp.abs2.imgAlt": "拦蓄洪水选址项目 — 塞姆南省",
  "pp.abs2.badge": "项目 02",
  "pp.abs2.status": "应用型项目 — 塞姆南省",
  "pp.abs2.h3": "用于拦蓄洪水选址的决策支持系统",
  "pp.abs2.h4": "塞姆南省 — 49 个适宜地点",
  "pp.abs2.p1": "本项目旨在为塞姆南省开发一套数据驱动的决策支持系统，用于拦蓄洪水（引洪灌溉）工程适宜场址的选址与排序。研究将机器学习、数字土壤制图（DSM）、ERA5-Land 再分析气候数据与 Landsat 8 卫星影像相结合，生成了覆盖全省的高精度土壤性质、气候与地表覆盖图件，其数据基础包括约 700 个土壤样品、1100 个土壤深度点以及 460 个植被冠层采样点。",
  "pp.abs2.p2": "利用 19 个辅助变量、多种机器学习模型（Random Forest、SVR、Treebag、Glmnet 及集成模型）和 Boruta 特征选择算法，提取了全省的洪水易发区，并基于 SCS 方法编制和率定了曲线数（CN）与径流深图。最后依据坡度（1–5%）、距水道距离、土壤深度、土地利用以及含水层存在性等准则，确定了 49 个适宜建设拦蓄洪水工程的场址，并经过野外核查后以最终图件形式交付。",
  "pp.abs2.meta1": "拦蓄洪水",
  "pp.abs2.meta2": "机器学习",
  "pp.abs2.meta3": "数字土壤制图",
  "pp.abs2.meta4": "空间决策支持",

