  "det2.abs.eyebrow": "项目摘要",
  "det2.abs.title": "省级尺度上拦蓄洪水场址的科学选址",
  "det2.abs.p1": "本项目为塞姆南省提供了一套数据驱动的决策支持系统，用于拦蓄洪水工程适宜场址的选址与排序。作为一种多功能措施，拦蓄洪水将水道中的径流与洪水引向平原，在降低洪水风险的同时补给地下水并遏制荒漠化。本研究首次在省级尺度上，将机器学习、数字土壤制图、再分析气候数据、Landsat 8 影像与野外数据相结合，生成了土壤、气候与地表覆盖等基础图件。",
  "det2.abs.p2": "在完成基础图件后，采用四种数据挖掘方法（RF、SVR、Treebag、Glmnet）结合集成策略与 Boruta 特征选择，提取了全省洪水易发区；基于 SCS 方法编制了曲线数（CN）与径流深图件，并用水文测站资料进行了率定。最后，依据坡度（1–5%）、距水道距离、土壤深度、土地利用和含水层存在性等筛选准则确定了 49 个适宜场址；在评估其上游条件（年径流量、土壤可蚀性与保水能力）后，最终图件连同野外验证结果一并交付。",
  "det2.prob.eyebrow": "问题陈述与项目必要性",
  "det2.prob.title": "为什么必须对拦蓄洪水进行科学选址？",
  "det2.prob.p": "水资源短缺是干旱与半干旱地区面临的主要挑战，全球约有 20 亿人处于水资源紧张状态。与此同时，洪水是 1995—2015 年间全球发生频率最高的自然灾害，影响约 23 亿人。在伊朗，约 20% 的降雨会转变为骤发性洪水，而塞姆南省占全国洪水损失的 21%。拦蓄洪水是兼具防洪与地下水补给功能的经济型多功能措施，但其成效关键在于科学选址并充分考虑上游条件。",
  "det2.chal1.num": "挑战 01",
  "det2.chal1.title": "水资源短缺与用水紧张",
  "det2.chal1.desc": "干旱和半干旱地区约有 20 亿人面临用水紧张，塞姆南省含水层补给不足的问题尤为突出。",
  "det2.chal2.num": "挑战 02",
  "det2.chal2.title": "洪水——全球第一大自然灾害",
  "det2.chal2.desc": "洪水以 56% 的占比成为 1995—2015 年全球最常见的自然灾害，也是伊朗三大主要自然灾害之一。",
  "det2.chal3.num": "挑战 03",
  "det2.chal3.title": "传统选址的局限",
  "det2.chal3.desc": "传统选址往往精度不足，且对所选场址的上游条件重视不够，削弱了工程的实际效果。",
  "det2.chal4.num": "挑战 04",
  "det2.chal4.title": "基础数据匮乏",
  "det2.chal4.desc": "全省范围内可靠的土壤、气候与洪水风险信息不足，必须借助现代方法编制数字基础图件。",
  "det2.prob.lead": "本项目的目标是将分散的土壤、气候与地表覆盖数据转化为一套决策支持系统，实现拦蓄洪水的优化选址，同时缓解洪水风险与水资源短缺问题。",
  "det2.obj.eyebrow": "研究目标",
  "det2.obj.title": "项目主要目标",
  "det2.obj1": "为塞姆南省提供一套数据驱动的决策支持系统，用于拦蓄洪水工程适宜场址的选址与排序。",
  "det2.obj2": "基于约 700 个土壤样品，利用数字土壤制图编制土壤性质基础图件（质地、有机碳、可蚀性和饱和导水率）。",
  "det2.obj3": "结合台站实测资料对 ERA5-Land 降水和温度数据进行插值与偏差校正，编制全省 30 年高精度气候图件。",
  "det2.obj4": "综合 19 个辅助变量、CN 与径流深图件，采用四种数据挖掘方法和 Boruta 算法提取全省洪水易发区。",
  "det2.obj5": "根据坡度、距水道距离、土壤深度、土地利用和含水层存在性对适宜场址进行遴选，确定 49 个最终点位。",
  "det2.obj6": "评估各建议点位的上游条件（年径流量、CN、可蚀性与保水能力），并通过野外调查对结果进行验证。",
  "det2.tech.eyebrow": "技术与方法",
  "det2.tech.title": "项目的先进工具与数据",
  "det2.tech1.t": "机器学习",
  "det2.tech1.d": "Random Forest、SVR、Treebag 与 Glmnet 四种数据挖掘方法，结合集成策略和 Boruta 特征选择算法用于空间建模。",
  "det2.tech2.t": "数字土壤制图",
  "det2.tech2.d": "利用 DEM、Landsat 8 与地质图层导出的辅助变量，基于约 700 个样品编制全省土壤图件。",
  "det2.tech3.t": "再分析气候数据",
  "det2.tech3.d": "采用 ERA5-Land 数据，并依据省内气象台站资料通过分位数映射方法进行偏差校正。",
  "det2.tech4.t": "遥感",
  "det2.tech4.d": "使用 Landsat 8（OLI）影像及 NDVI、MSAVI 指数，编制冠层覆盖度与地表覆盖图件。",
  "det2.tech5.t": "水文模拟",
  "det2.tech5.d": "基于 Ks 与 LULC 数据编制曲线数（CN）图，运用 SCS 方法估算径流深，并以水文测站数据进行率定。",
  "det2.tech6.t": "地理空间分析",
  "det2.tech6.d": "在 GIS 环境中提取 DEM 衍生产物（坡度、坡向、TWI、SPI、STI、曲率等），用于洪水易发区建模。",
  "det2.act.eyebrow": "所开展的工作",
  "det2.act.title": "野外、实验室与建模实施",
  "det2.act1.t": "土壤采样与实验室分析",
  "det2.act1.d": "采集约 700 个土壤样品，测定粉粒、砂粒、黏粒与有机碳，并依据 Saxton & Rawls 方法估算可蚀性与饱和导水率。",
  "det2.act2.t": "气候与卫星数据处理",
  "det2.act2.d": "汇集气象台站资料，处理 ERA5-Land 与 Landsat 8 影像，并完成 460 个冠层覆盖点的采样。",
  "det2.act3.t": "建模、选址与验证",
  "det2.act3.d": "提取洪水易发区、编制 CN 与径流深图件、遴选 49 个拦蓄洪水场址并对结果进行野外核查。",
  "det2.maps.eyebrow": "图件画廊",
  "det2.maps.title": "项目图件",
  "det2.maps.desc": "以下画廊展示了研究过程中生成的空间成果；点击任意图件可查看放大视图。",
