  "det2.res.eyebrow": "项目成果",
  "det2.res.title": "从零散数据到最终选址图",
  "det2.res.p1": "本项目最重要的成果，是编制了塞姆南省首批数字基础图件（土壤、气候与地表覆盖），并将其转化为拦蓄洪水决策支持系统。洪水易发区以四种数据挖掘方法提取并达到可评估的精度，曲线数与径流深图件经编制与率定后，最终以一份经过验证的图件交付了 49 个适宜建设拦蓄洪水工程的区域。",
  "det2.res.p2": "除拦蓄洪水选址外，这一技术基础设施还可服务于含水层管理、水资源规划、沙尘监测以及省域自然资源战略决策，并可在新数据输入时方便地更新。",
  "det2.fut.eyebrow": "未来方向",
  "det2.fut.title": "将系统推广至更多应用场景",
  "det2.fut.p1": "随着全省数字土壤图件的完善（将采样点从约 700 个增加至所需 5000 个以上）、空间数据库的扩充、雷达影像在干旱与半干旱区洪水监测中的应用，以及结果与在线监测系统的对接，该基础设施有望发展为全国性的水土保持与人工补给工程选址平台。",

  /* ---------- 项目03 — 表格与摘要 ---------- */
  "pp.tab.row3.title": "砾石覆盖在防治风蚀中的效果研究（以加姆萨尔地区为例）",
  "pp.tab.row3.basin": "加姆萨尔地区，塞姆南省",
  "pp.tab.row3.status": "已完成",
  "pp.abs3.title": "砾石覆盖在防治风蚀中的效果研究",
  "pp.abs3.basin": "研究区域：加姆萨尔地区，塞姆南省",
  "pp.abs3.imgAlt": "砾石覆盖项目 — 加姆萨尔",
  "pp.abs3.badge": "项目 03",
  "pp.abs3.status": "应用研究项目",
  "pp.abs3.h3": "砾石覆盖：防治风蚀的可持续方案",
  "pp.abs3.h4": "加姆萨尔地区 — 风洞与野外研究",
  "pp.abs3.p1": "本项目通过风洞试验与野外研究相结合，评估了砾石覆盖在加姆萨尔地区荒漠土地中风蚀防治方面的效果。研究区年降水量约 117 毫米、年蒸发蒸腾达 2550 毫米以上，盛行西—东风，土壤多石膏质与盐渍化，是风蚀最敏感的区域之一。研究选取七个砾石覆盖处理（10%–70%），在六种风速下采用完全随机设计的析因试验，三次重复。",
  "pp.abs3.p2": "结果表明，砾石覆盖使风蚀减少 98% 以上（从对照处理的 22.73 克降至 70% 覆盖时的 0.39 克），其中 50%、60% 和 70% 三种覆盖效果最佳。将土壤含水率提高至 2% 可使风蚀减少 99% 以上。从经济角度估算，所选覆盖的覆盖铺设成本为每公顷 1.3 亿至 2.52 亿托曼，50% 覆盖被推荐为首选方案。",
  "pp.abs3.meta1": "砾石覆盖",
  "pp.abs3.meta2": "风蚀",
  "pp.abs3.meta3": "风洞",
  "pp.abs3.meta4": "荒漠治理",

  "det3.hero.eyebrow": "项目 03 — 详情",
  "det3.hero.title": "砾石覆盖在防治风蚀中的效果研究",
