  "det3.spec.eyebrow": "总体概况",
  "det3.spec.title": "项目档案",
  "det3.spec.k1": "项目名称",
  "det3.spec.v1": "砾石覆盖在防治风蚀中的效果研究（以加姆萨尔地区为例）",
