  "det3.spec.k4": "研究区域",
  "det3.spec.v4": "加姆萨尔县加姆萨尔—库姆公路下游的荒漠土地（已铺设覆盖约 40 公顷）",
  "det3.spec.k5": "区域气候",
  "det3.spec.v5": "炎热干旱的沙漠气候；年均降水量约 117 毫米；年潜在蒸发蒸腾超过 2550 毫米；年均气温约 19°C",
  "det3.spec.k6": "土壤特征",
  "det3.spec.v6": "石膏质与盐渍化土壤，植被覆盖不足 1%，土质易发生风蚀",
