  "leader.p1": "الدكتور علي أصغر ذوالفقاري أستاذ مشارك في قسم مكافحة التصحر ورئيس كلية علوم الصحراء بجامعة سمنان. حاصل على بكالوريوس من جامعة جيلان وماجستير من جامعة أصفهان التكنولوجية ودكتوراه من جامعة طهران. وتشمل مجالاته التخصصية والبحثية مكافحة التصحر والتربة والمياه وتعرية التربة والهيدرولوجيا وتغير المناخ والاستشعار عن بعد ونظم المعلومات الجغرافية والنمذجة البيئية وتطبيق التعلم الآلي في علوم الموارد الطبيعية.",
