  "pp.abs.h3": "إطار ذكي لإدارة الأحواض المائية",
  "pp.abs.h4": "حوض فولاد محلة — مهدي شهر",
  "pp.abs.p1": "صُمم هذا المشروع ونُفذ بهدف تطوير إطار ذكي قائم على البيانات والذكاء الاصطناعي لتحليل وإدارة الأحواض المائية. وفي هذا البحث، تم دمج تقنيات الاستشعار عن بعد ونظم المعلومات الجغرافية (GIS) والبيانات المناخية الضخمة والنمذجة الرقمية للتضاريس وخوارزميات التعلم الآلي لإنشاء منصة موحدة لتحليل السلوك الهيدرولوجي والجيومورفولوجي للحوض.",
  "pp.abs.p2": "ما يميز هذا المشروع عن الدراسات التقليدية هو التحول من التحليلات الكلاسيكية إلى التحليلات الذكية القائمة على البيانات؛ إذ لم تُبنَ القرارات الإدارية على علاقات تجريبية محدودة، بل على المعالجة المتزامنة للبيانات متعددة المصادر والنماذج التنبؤية والتحليلات المكانية المتقدمة.",
