  "det.act.eyebrow": "الأنشطة المنفذة",
  "det.act.title": "التنفيذ الميداني والتخصصي للمشروع",
  "det.act1.t": "جلسة تخصصية وتخطيط تنفيذ المشروع",
  "det.act1.d": "عقد جلسات تخصصية لصياغة خارطة الطريق التنفيذية والتنسيق بين القطاعات.",
  "det.act2.t": "زيارة ميدانية للحوض",
  "det.act2.d": "زيارة الحوض المائي برفقة خبراء الإدارة العامة للموارد الطبيعية وأعضاء المجلس وأمانة القرى وأعضاء المشروع.",
  "det.act3.t": "أخذ العينات وفحوص المياه والتربة",
  "det.act3.d": "تنفيذ أخذ العينات وفحوص المياه والتربة لدعم نمذجة التعرية والمحاكاة الهيدرولوجية.",
  "det.gal.eyebrow": "معرض الأنشطة",
  "det.gal.title": "التقرير المصور للمشروع",
  "det.gal.desc": "تُسجّل الأنشطة الميدانية والتخصصية للمشروع حسب الترتيب الزمني في الأطر التالية؛ وعند توفر كل صورة يُستكمل الإطار المقابل.",
  "det.tl1.ph": "موضع الصورة — الجلسة التخصصية",
  "det.tl1.t": "جلسة تخصصية وتخطيط تنفيذ المشروع",
  "det.tl1.d": "جلسات تنسيق بين القطاعات وصياغة خارطة الطريق التنفيذية بحضور الخبراء وأعضاء النواة.",
  "det.tl2.ph": "موضع الصورة — الزيارة الميدانية",
  "det.tl2.t": "زيارة الحوض رفقة الخبراء",
  "det.tl2.d": "معاينة ميدانية للحوض المائي بمشاركة الإدارة العامة للموارد الطبيعية وأعضاء المجلس وأمانة القرى وأعضاء المشروع.",
  "det.tl3.ph": "موضع الصورة — أخذ العينات",
  "det.tl3.t": "أخذ العينات وفحوص المياه والتربة",
  "det.tl3.d": "جمع عينات المياه والتربة وإجراء الفحوص المخبرية لنمذجة دقيقة لسلوك الحوض.",
  "det.tl4.ph": "موضع الصورة — التحليل والنمذجة",
  "det.tl4.t": "تحليل البيانات والنمذجة الذكية",
  "det.tl4.d": "دمج البيانات متعددة المصادر والنمذجة الهيدرولوجية وإنتاج المخرجات المكانية والتحليلية.",
  "det.adv.eyebrow": "الميزة التنافسية",
  "det.adv.title": "تميز هذا المشروع عن الدراسات التقليدية",
  "det.adv.p": "يتجاوز هذا المشروع الدراسة الوصفية البحتة، وقد أتاح، عبر إنشاء قاعدة تحليل مكاني شاملة، إمكانية نمذجة دقيقة لسلوك الحوض.",
  "det.adv1": "زيادة دقة التحليلات الهيدرولوجية والجيومورفولوجية عبر معالجة البيانات متعددة المصادر.",
  "det.adv2": "تقليص عدم اليقين في عملية اتخاذ القرار الإداري.",
  "det.adv3": "تقليص كلفة ووقت الدراسات الميدانية عبر التوظيف الأمثل لتقنيات الجيوماتكس.",
  "det.adv4": "إتاحة تحديث سريع للمعلومات عند توفر بيانات جديدة.",
  "det.adv5": "إنتاج مخرجات معيارية قابلة للاستخدام في مشاريع حفظ الأحواض المائية الوطنية.",
  "det.adv6": "توفير البنية اللازمة لتطوير أنظمة ذكية لإدارة الموارد الطبيعية.",
  "det.techach.eyebrow": "الإنجاز التقني",
  "det.techach.title": "من الدراسة الوصفية إلى نظام التنبؤ واتخاذ القرار",
  "det.techach.p1": "رقّى هذا البحث، عبر إنشاء بنية ذكية قائمة على البيانات الساتلية والبيانات المناخية الضخمة والتحليلات الجغرافية المكانية وخوارزميات التعلم الآلي، عملية دراسات الأحواض المائية من أسلوب تقليدي وصفي إلى نظام متقدم للتحليل والتنبؤ واتخاذ القرار. وقد أتاح الدمج المتزامن لبيانات ERA5-Land وCHIRPS وIMERG مع نماذج التعلم الآلي وتحليلات GIS تحديد الأنماط الخفية وتقليص عدم اليقين ورفع دقة التنبؤ وتخفيض كلف القياس الميداني وتحسين القرارات الإدارية.",
  "det.techach.p2": "من الناحية التقنية، يعد هذا المشروع نموذجًا لتطبيق الذكاء الاصطناعي والتحليلات الجغرافية المكانية المتقدمة في إدارة الموارد الطبيعية، ويمتلك قابلية التوسع نحو أنظمة الرصد الذكية والتنبؤ بالمخاطر الطبيعية وإدارة السيول وتقييم التعرية والتخطيط القائم على البيانات للأحواض المائية.",
  "det.future.eyebrow": "أفق تطوير التقنية",
  "det.future.title": "المسار المستقبلي والقيمة المضافة الوطنية",
  "det.future.p1": "تمتلك البنية التي أُنشئت في هذا المشروع قابلية التوسع نحو جيل جديد من أنظمة الإدارة الذكية للموارد الطبيعية، ويمكن أن تشكل أساسًا لتطوير أنظمة الرصد المستمر للأحواض المائية والتحليلات القائمة على التنبؤ وتقييم الأخطار البيئية وأنظمة دعم القرار في تخطيط الأراضي. وليس هذا المشروع دراسة تنفيذية فحسب، بل منصة تقنية لإدارة الموارد الطبيعية القائمة على البيانات.",
  "det.future.p2": "يقدّم هذا المشروع، عبر التآزر بين الذكاء الاصطناعي والاستشعار عن بعد والبيانات الساتلية والمناخية وGIS والنمذجة الهيدرولوجية، نموذجًا جديدًا للإدارة الذكية للأحواض المائية؛ وهو إنجاز لا يقتصر على إنتاج الخرائط أو التقارير، بل بناء إطار تقني قابل للتوسع والتكرار والتوطين لباقي أحواض البلاد.",
  "det.back": "العودة إلى قائمة المشاريع",

