  /* ---------- المشروع 02 — الجدول والملخص ---------- */
  "pp.tab.row2.title": "تطوير نظام دعم القرار لتحديد مواقع وترتيب المناطق المؤهلة لنشر مياه الأمطار والسيول في محافظة سمنان",
  "pp.tab.row2.basin": "محافظة سمنان",
  "pp.tab.row2.status": "مكتمل",
  "pp.abs2.title": "تطوير نظام دعم القرار لتحديد مواقع وترتيب المناطق المؤهلة لنشر مياه الأمطار والسيول في محافظة سمنان",
  "pp.abs2.basin": "منطقة الدراسة: محافظة سمنان",
  "pp.abs2.imgAlt": "مشروع تحديد مواقع نشر السيول — محافظة سمنان",
  "pp.abs2.badge": "المشروع 02",
  "pp.abs2.status": "مشروع تطبيقي — محافظة سمنان",
  "pp.abs2.h3": "نظام دعم القرار لتحديد مواقع نشر السيول",
  "pp.abs2.h4": "محافظة سمنان — ٤٩ موقعًا مؤهلًا",
  "pp.abs2.p1": "صُمِّم هذا المشروع ونُفِّذ لتطوير نظام دعم قرار مبنٍ على البيانات لتحديد وترتيب المناطق المؤهلة لنشر مياه الأمطار والسيول في محافظة سمنان. ومن خلال تكامل التعلم الآلي، والرسم الرقمي للتربة (DSM)، وبيانات المناخ ERA5-Land، وصور القمر الصناعي Landsat 8، أُنتجت خرائط تفصيلية لخصائص التربة والمناخ والغطاء الأرضي على مستوى المحافظة كافة، مستندة إلى نحو ٧٠٠ عينة تربة، و١٬١٠٠ نقطة لعمق التربة، و٤٦٠ نقطة لقياس الغطاء التاجي.",
  "pp.abs2.p2": "باستخدام ١٩ متغيرًا مساعدًا ونماذج التعلم الآلي (Random Forest وSVR وTreebag وGlmnet والنموذج التجميعي) وخوارزمية اختيار الميزات Boruta، استُخرجت مناطق التعرض للسيول في المحافظة، وأُعدّت خرائط رقم المنحنى (CN) وعمق الجريان السطحي وتمت معايرتها بطريقة SCS. وفي الخطوة الأخيرة، وبعد تطبيق معايير كالانحدار (١–٥٪) والبعد عن المجاري المائية وعمق التربة وتصنيف الأراضي ووجود المكامن المائية، حُدِّد ٤٩ موقعًا مؤهلًا لنشر السيول، وخضعت جميعها للتحقق الميداني ووُسِّمت على الخريطة النهائية.",
  "pp.abs2.meta1": "نشر المياه والسيول",
  "pp.abs2.meta2": "التعلم الآلي",
  "pp.abs2.meta3": "الرسم الرقمي للتربة",
  "pp.abs2.meta4": "اتخاذ القرار المكاني",

  "det2.hero.eyebrow": "المشروع 02 — التفاصيل",
  "det2.hero.title": "نظام دعم القرار لتحديد مواقع نشر السيول في محافظة سمنان",
  "det2.hero.h2": "محافظة سمنان",
  "det2.hero.desc": "يجمع هذا المشروع بين بيانات التربة والمناخ والاستشعار عن بُعد ونماذج التعلم الآلي لتقديم إطار متكامل لتحديد وترتيب المناطق المؤهلة لنشر مياه السيول في محافظة سمنان. ونتيجته خريطة نهائية تضم ٤٩ موقعًا مؤهلًا، مصحوبة بتحليل الظروف المنبعية لهذه المواقع.",
