  "det2.stat1.num": "٧٠٠",
  "det2.stat1.label": "عينة تربة جُمعت من أنحاء المحافظة",
  "det2.stat2.num": "٤٩",
  "det2.stat2.label": "موقعًا مؤهلًا لنشر مياه السيول",
  "det2.stat3.num": "١٩",
  "det2.stat3.label": "متغيرًا مساعدًا للنمذجة المكانية",
  "det2.stat4.num": "١٣",
  "det2.stat4.label": "فئة مستحدثة لتصنيف الأراضي (LULC)",
  "det2.abs.eyebrow": "ملخص المشروع",
  "det2.abs.title": "تحديد المواقع علميًا على مستوى المحافظة",
  "det2.abs.p1": "يقدّم هذا المشروع نظام دعم قرار مبنٍ على البيانات لتحديد وترتيب المناطق المؤهلة لنشر مياه السيول في محافظة سمنان. وبوصفه إجراءً متعدد الأغراض، ينقل نشر السيول الجريانَ والمياهَ المتجمعة من المجاري المائية إلى السهول، فيحدّ من مخاطر الفيضانات ويعيد شحن المياه الجوفية ويبطئ التصحر. ولأول مرة على مستوى المحافظة، جمع هذا البحث بين التعلم الآلي والرسم الرقمي للتربة وبيانات المناخ المتكسرة وصور Landsat 8 والبيانات الميدانية لإنتاج خرائط أساسية للتربة والمناخ والغطاء الأرضي.",
  "det2.abs.p2": "بعد إعداد الخرائط الأساسية، استُخرجت مناطق التعرض للسيول بأربع طرائق لتنقيب البيانات (RF وSVR وTreebag وGlmnet) ضمن نهج تجميعي مع اختيار ميزات Boruta. وأُعدّت خرائط رقم المنحنى (CN) وعمق الجريان السطحي بأسلوب SCS وعُوملت على أساس بيانات المحطات الهيدرومترية. وفي الخطوة الأخيرة، حُدِّد ٤٩ موقعًا مؤهلًا لنشر السيول بعد تطبيق مرشحات الانحدار (١–٥٪) والبعد عن المجاري وعمق التربة وتصنيف الأراضي ووجود المكامن؛ وبعد تقييم الظروف المنبعية (الجريان السنوي، وقابلية الانجراف، والاحتفاظ بالمياه)، وُسِّمت خريطة نهائية مع تحقق ميداني.",
  "det2.prob.eyebrow": "بيان المشكلة وضرورة المشروع",
  "det2.prob.title": "لماذا يجب تحديد مواقع نشر السيول علميًا؟",
  "det2.prob.p": "تُمثِّل شحُّ المياه تحديًا كبيرًا في المناطق الجافة وشبه الجافة، إذ يعيش نحو ملياري إنسان تحت ضغط مائي. وفي الوقت نفسه، كانت الفيضانات أكثر الكوارث الطبيعية تكرارًا في العالم بين عامَي ١٩٩٥ و٢٠١٥، إذ أثرت في نحو ٢٫٣ مليار شخص. وفي إيران يتحول نحو ٢٠٪ من الأمطار إلى سيول مفاجئة، وتحتل محافظة سمنان نسبة ٢١٪ من أضرار السيول في البلاد. ونشر السيول إجراء متعدد الأغراض ومنخفض التكلفة لضبط الفيضانات وإعادة شحن المياه الجوفية، لكن نجاحه مرهون بدقة تحديد المواقع ودراسة الظروف المنبعية.",
  "det2.chal1.num": "التحدي 01",
  "det2.chal1.title": "شحّ المياه والضغط المائي",
  "det2.chal1.desc": "يعيش نحو ملياري إنسان في المناطق الجافة وشبه الجافة تحت ضغط مائي، وعدم كفاية تغذية المكامن المائية في محافظة سمنان واضح تمامًا.",
  "det2.chal2.num": "التحدي 02",
  "det2.chal2.title": "الفيضانات الكارثة الأولى عالميًا",
  "det2.chal2.desc": "مثّلت الفيضانات بنسبة ٥٦٪ أكثر الكوارث الطبيعية تكرارًا في العالم (١٩٩٥–٢٠١٥)، وتبقى من الكوارث الطبيعية الرئيسية الثلاث في إيران.",
  "det2.chal3.num": "التحدي 03",
  "det2.chal3.title": "محدودية التحديد التقليدي للمواقع",
  "det2.chal3.desc": "غالبًا ما يكون التحديد التقليدي غير دقيق بما يكفي ويُهمل الظروف المنبعية للمواقع، مما يقلّل من فاعلية المشاريع.",
  "det2.chal4.num": "التحدي 04",
  "det2.chal4.title": "غياب البيانات الأساسية",
  "det2.chal4.desc": "إن نُدرة معلومات التربة والمناخ ومخاطر السيول الموثوقة على مستوى المحافظة تجعل إنتاج الخرائط الرقمية الأساسية بالطرائق الحديثة أمرًا لا غنى عنه.",
  "det2.prob.lead": "يهدف المشروع إلى تحويل بيانات التربة والمناخ والغطاء الأرضي المتناثرة إلى نظام دعم قرار للتحديد الأمثل لمواقع نشر السيول، بما يخفّف في آنٍ معًا مخاطر الفيضانات وشحّ المياه.",
  "det2.obj.eyebrow": "أهداف الدراسة",
  "det2.obj.title": "الأهداف الرئيسية للمشروع",
  "det2.obj1": "تقديم نظام دعم قرار مبنٍ على البيانات لتحديد وترتيب المناطق المؤهلة لنشر مياه السيول في محافظة سمنان.",
  "det2.obj2": "إنتاج خرائط أساسية لخصائص التربة (القوام، والكربون العضوي، والقابلية للانجراف، والتوصيل الهيدروليكي المشبع) عبر الرسم الرقمي للتربة من نحو ٧٠٠ عينة.",
  "det2.obj3": "استيفاء بيانات هطول وتفريغ ERA5-Land وتصحيح انحرافها وفقًا لبيانات المحطات، وإعداد خرائط مناخية دقيقة للمحافظة تغطي ٣٠ عامًا.",
  "det2.obj4": "استخراج مناطق التعرض للسيول بأربع طرائق لتنقيب البيانات وبتقنية Boruta وبـ ١٩ متغيرًا مساعدًا وخرائط CN وعمق الجريان.",
  "det2.obj5": "تحديد مناطق نشر السيول استنادًا إلى الانحدار والبعد عن المجاري المائية وعمق التربة وتصنيف الأراضي ووجود المكامن، واعتماد ٤٩ موقعًا نهائيًا.",
  "det2.obj6": "تقييم الظروف المنبعية للمواقع المقترحة (حجم الجريان السنوي، CN، قابلية الانجراف، والاحتفاظ بالمياه) والتحقق من النتائج بالمسوحات الميدانية.",
  "det2.tech.eyebrow": "التقنيات والأساليب",
