  "det2.maps.cap23": "الكربون العضوي للتربة",
  "det2.res.eyebrow": "إنجازات المشروع",
  "det2.res.title": "من البيانات المتناثرة إلى الخريطة النهائية",
  "det2.res.p1": "أهم إنجاز لهذا المشروع هو إنشاء أول مجموعة خرائط رقمية أساسية (للتربة والمناخ والغطاء الأرضي) على مستوى المحافظة، وتحويلها إلى نظام دعم قرار لنشر السيول. وقد استُخرجت مناطق التعرض للسيول بأربع طرائق تنقيب بدقة قابلة للتقييم، وأُعدّت وعُوملت خرائط رقم المنحنى وعمق الجريان، وفي النهاية سُلّمت ٤٩ منطقة مؤهلة لنشر مياه السيول في خريطة واحدة محقَّقة.",
  "det2.res.p2": "إلى جانب تحديد مواقع مشاريع نشر السيول، تدعم هذه البنية التقنية إدارة المكامن المائية وتخطيط الموارد المائية ورصد الغبار واتخاذ القرار الاستراتيجي للموارد الطبيعية في محافظة سمنان، ويسهل تحديثها عند توفر بيانات جديدة.",
  "det2.fut.eyebrow": "الاتجاه المستقبلي",
  "det2.fut.title": "توسيع النظام ليشمل تطبيقات أخرى",
  "det2.fut.p1": "بإكمال الخرائط الرقمية للتربة في المحافظة (رفع نقاط العينات من نحو ٧٠٠ إلى أكثر من ٥٬٠٠٠ المطلوبة)، وتوسيع قاعدة البيانات المكانية، واستخدام صور الرادار لرصد مناطق السيول في الأراضي الجافة وشبه الجافة، وربط النتائج بأنظمة الرصد عبر الإنترنت، يمكن أن تنمو هذه البنية لتصبح منصة وطنية لتحديد مواقع مشاريع إدارة أحواض المياه والتغذية الاصطناعية.",

  /* ---------- المشروع 03 — الجدول والملخص ---------- */
  "pp.tab.row3.title": "دراسة فاعلية النشارة الحصوية في مكافحة الانجراف الريحي (دراسة حالة: منطقة جرمسار)",
  "pp.tab.row3.basin": "منطقة جرمسار، محافظة سمنان",
  "pp.tab.row3.status": "مكتمل",
  "pp.abs3.title": "دراسة فاعلية النشارة الحصوية في مكافحة الانجراف الريحي",
  "pp.abs3.basin": "منطقة الدراسة: منطقة جرمسار، محافظة سمنان",
  "pp.abs3.imgAlt": "مشروع النشارة الحصوية — جرمسار",
  "pp.abs3.badge": "المشروع 03",
  "pp.abs3.status": "مشروع بحث تطبيقي",
  "pp.abs3.h3": "النشارة الحصوية: حل مستدام للحد من الانجراف الريحي",
  "pp.abs3.h4": "منطقة جرمسار — دراسات نفق الرياح والميدان",
  "pp.abs3.p1": "في هذا المشروع، قُيّمت فاعلية النشارة الحصوية في مكافحة الانجراف الريحي في الأراضي الصحراوية بمنطقة جرمسار عبر الجمع بين تجارب نفق الرياح والدراسات الميدانية. وبمعدل هطول سنوي يبلغ نحو ١١٧ ملم، وبخر-نتح يتجاوز ٢٬٥٥٠ ملم، ورياح سائدة من الغرب إلى الشرق، وتربة جبسية ومالحة، تُعد منطقة الدراسة من أكثر الأراضي عرضة للانجراف الريحي. واختُبر تأثير سبعة معاملات تغطية حصوية (١٠–٧٠٪) عند ست سرعات رياح في تصميم مضروب كاملًا عشوائيًا بثلاث تكرارات.",
  "pp.abs3.p2": "أظهرت النتائج أن النشارة الحصوية تقلّل الانجراف الريحي بنسبة تتجاوز ٩٨٪ (من ٢٢٫٧٣ غرامًا في معاملة الشاهد إلى ٠٫٣٩ غرامًا عند تغطية ٧٠٪)، وكانت معاملات ٥٠٪ و٦٠٪ و٧٠٪ الأفضل أداءً. ورفع رطوبة التربة إلى ٢٪ خفّض الانجراف بأكثر من ٩٩٪. ومن الوجهة الاقتصادية، قُدّرت تكلفة فرش الحصى للتغطيات المختارة بـ ١٣٠–٢٥٢ مليون تومان لكل هكتار، واعتُمدت التغطية ٥٠٪ خيارًا موصىً به.",
  "pp.abs3.meta1": "النشارة الحصوية",
  "pp.abs3.meta2": "الانجراف الريحي",
  "pp.abs3.meta3": "نفق الرياح",
  "pp.abs3.meta4": "إدارة الأراضي الصحراوية",

  "det3.hero.eyebrow": "المشروع 03 — التفاصيل",
  "det3.hero.title": "دراسة فاعلية النشارة الحصوية في مكافحة الانجراف الريحي",
  "det3.hero.h2": "منطقة جرمسار، محافظة سمنان",
  "det3.hero.desc": "تقييم مخبري وميداني لأثر النشارة الحصوية على معدل الانجراف الريحي في الأراضي الصحراوية بجرمسار — مشروع يؤكد الفاعلية العالية لهذه الطريقة الأهلية والمستدامة والاقتصادية في الحد من الغبار وتثبيت التربة.",
