  "det3.spec.v5": "صحراوي حار وجاف؛ متوسط الهطول السنوي نحو ١١٧ ملم؛ بخر-نتح محتمل سنوي يتجاوز ٢٬٥٥٠ ملم؛ متوسط الحرارة السنوي نحو ١٩ درجة مئوية",
