  "det3.stat2.num": "٠٫٣٩",
  "det3.stat2.label": "غرام من انجراف التربة عند أفضل تغطية (٧٠٪) مقابل ٢٢٫٧٣ غرامًا في الشاهد",
  "det3.stat3.num": "٦٫٤٩–٧٫١١",
  "det3.stat3.label": "مدى سرعة عتبة الانجراف (م/ث) عبر المعاملات",
  "det3.stat4.num": "١٣٠–٢٥٢",
  "det3.stat4.label": "تكلفة فرش الحصى (مليون تومان لكل هكتار)",
  "det3.abs.eyebrow": "ملخص المشروع",
  "det3.abs.title": "تثبيت التربة الصحراوية بالنشارة الحصوية",
  "det3.abs.p1": "يعد الانجراف الريحي من أهم التحديات البيئية والاقتصادية في المناطق الجافة وشبه الجافة؛ إذ ينقل حبيبات التربة ويفكك بنيتها وينشر الغبار، مهددًا استقرار النظم البيئية وصحة الإنسان. والنشارة الحصوية غطاء سطحي، دون أي مدخلات كيميائية، يزيد خشونة السطح ويخفّض سرعة الرياح قرب الأرض ويشكّل طبقة حماية فيزيائية تمنع اقتلاع حبيبات التربة ونقلها. وفي هذا المشروع، قُيّم أداؤها في الأراضي الصحراوية بمنطقة جرمسار بواسطة نفق الرياح والدراسات الميدانية.",
  "det3.abs.p2": "أُجريت التجارب وفق تصميم مضروب في ترتيب عشوائي كامل بثلاث تكرارات، شمل سبعة معاملات تغطية حصوية (١٠–٧٠٪) وست سرعات رياح. وأظهرت النتائج تخفيضًا في الانجراف يتجاوز ٩٨٪ (من ٢٢٫٧٣ إلى ٠٫٣٩ غرامًا)؛ وكانت معاملات ٥٠٪ و٦٠٪ و٧٠٪ الأفضل إحصائيًا والمتشابهة فيما بينها. وخفّضت رطوبة التربة البالغة ٢٪ الانجراف بأكثر من ٩٩٪، كما أدت النشارة الحصوية إلى خفض التوصيل الكهربائي والصوديوم الذائب ونسبة امتزاز الصوديوم بنسب ٤٢٪ و٦١٪ و٤٤٪ على التوالي. وأوصى التحليل الاقتصادي بدوره بتغطية ٥٠٪ بوصفها الخيار الأمثل.",
  "det3.area.eyebrow": "منطقة الدراسة",
  "det3.area.title": "جرمسار: أراضٍ شديدة التعرض للانجراف الريحي",
  "det3.area.p": "تقع منطقة الدراسة في الأراضي الصحراوية أسفل طريق جرمسار–قم (مقاطعة جرمسار، محافظة سمنان). وتتمتع المنطقة بمناخ صحراوي حار وجاف: يبلغ متوسط الهطول السنوي المسجل في محطة جرمسار السينوبتيكية نحو ١١٧ ملم، يهطل معظمه شتاءً وربيعًا. وتبلغ الحرارة السنوية نحو ١٩ درجة مئوية، ويتجاوز البخر-نتح المحتمل السنوي ٢٬٥٥٠ ملم. أما الرياح السائدة فغربية–شرقية غالبًا، وتصل في بعض الفصول إلى سرعات ملحوظة تثير انجرافًا ريحيًا واسعًا.",
  "det3.area1.n": "هطول محدود",
  "det3.area1.t": "أيام مطر قليلة",
  "det3.area1.d": "متوسط هطول سنوي نحو ١١٧ ملم، يهطل معظمه شتاءً وربيعًا.",
  "det3.area2.n": "بخر-نتح مرتفع",
  "det3.area2.t": "عجز مائي حاد",
  "det3.area2.d": "بخر-نتح محتمل سنوي يتجاوز ٢٬٥٥٠ ملم، مما يزيد عجز رطوبة التربة.",
  "det3.area3.n": "تربة جبسية ومالحة",
  "det3.area3.t": "تشكيلات مالحة وجبسية",
  "det3.area3.d": "نوى الملح والمعادن الجبسية داخل التربة تمنحها قدرة عالية على الانجراف الريحي.",
  "det3.area4.n": "غطاء نباتي ضئيل",
  "det3.area4.t": "تغطية متفرقة للغاية",
  "det3.area4.d": "غطاء نباتي أقل من ١٪، ويقترب من الصفر في معظم المواقع.",
  "det3.method.eyebrow": "منهجية البحث",
  "det3.method.title": "الجمع بين الدراسات الميدانية وتجارب نفق الرياح",
  "det3.method.p": "أُجريت الدراسات ميدانيًا ومخبريًا. ميدانيًا، نُقل نفق الرياح إلى الموقع لقياس سرعة عتبة الانجراف في المواقع المفروشة وغير المفروشة، وفُحصت مقاطع رطوبة التربة وقابلية التسرب على انفراد. مخبريًا، عُولجت بيانات ٣٠ عامًا من محطة جرمسار السينوبتيكية، ورُسمت وردة الرياح، وقورنت الخصائص الفيزيائية–الكيميائية للتربة على ثلاثة أعماق (٠–٣٠ و٣٠–٦٠ و٦٠–٩٠ سم) بين المنطقتين المفروشة وغير المفروشة. ثم وُزعت معاملات الحصى عشوائيًا على أطباق نفق الرياح واختُبرت عند ست سرعات رياح.",
  "det3.method1.t": "الدراسات الميدانية",
  "det3.method1.d": "تحديد سرعة عتبة الانجراف بنفق الرياح ومقياس الرياح، وقياس مقاطع رطوبة التربة وقابلية التسرب في الميدان.",
  "det3.method2.t": "التجارب المخبرية",
